import os
import numpy as np
import torch
import torch.nn as nn
import torch.optim as optim
from torch.utils.data import Dataset, DataLoader
from datasets import load_dataset

# Prepare working directory
working_dir = os.path.join(os.getcwd(), "working")
os.makedirs(working_dir, exist_ok=True)

# Device configuration
device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print(f"Using device: {device}")

# Load datasets from HuggingFace
datasets = {
    "dataset1": load_dataset("some_huggingface_dataset_1"),
    "dataset2": load_dataset("some_huggingface_dataset_2"),
    "dataset3": load_dataset("some_huggingface_dataset_3"),
}


# Dataset class for multi-turn interactions
class MultiTurnDataset(Dataset):
    def __init__(self, dataset):
        self.data = [(example["prompt"], example["response"]) for example in dataset]

    def __len__(self):
        return len(self.data)

    def __getitem__(self, idx):
        prompt, response = self.data[idx]
        return prompt, response


# Create dataloaders for each dataset
dataloaders = {
    name: DataLoader(MultiTurnDataset(data["train"]), batch_size=4, shuffle=True)
    for name, data in datasets.items()
}


# Simple LLM model
class SimpleLLM(nn.Module):
    def __init__(self):
        super(SimpleLLM, self).__init__()
        self.fc = nn.Sequential(
            nn.Linear(10, 64),
            nn.ReLU(),
            nn.Linear(64, 2),
        )

    def forward(self, x):
        return self.fc(x)


# Parameters
num_epochs = 5
learning_rate = 0.001

# Experiment data storage
experiment_data = {
    name: {"metrics": {"train": []}, "losses": {"train": []}}
    for name in datasets.keys()
}

# Training loop
for dataset_name, dataloader in dataloaders.items():
    model = SimpleLLM().to(device)
    optimizer = optim.Adam(model.parameters(), lr=learning_rate)
    criterion = nn.MSELoss()

    for epoch in range(num_epochs):
        model.train()
        total_loss = 0

        for prompts, responses in dataloader:
            inputs = torch.randn(len(prompts), 10).to(
                device
            )  # Random inputs for demonstration
            outputs = model(inputs)
            loss = criterion(
                outputs, torch.randn(len(prompts), 2).to(device)
            )  # Random target

            optimizer.zero_grad()
            loss.backward()
            optimizer.step()

            total_loss += loss.item()

        avg_loss = total_loss / len(dataloader)
        experiment_data[dataset_name]["losses"]["train"].append(avg_loss)

        # Collaborative Engagement Score (simulated)
        ces = np.random.rand()  # Replace with actual calculation in practice
        experiment_data[dataset_name]["metrics"]["train"].append(ces)

        print(
            f"{dataset_name} - Epoch {epoch + 1}/{num_epochs}: loss = {avg_loss:.4f}, CES = {ces:.4f}"
